with valid as (select *, concat(carrier, ', ', status) as carrier_status from shipments where carrier is not null), enriched as (select id, order_id, carrier, shipped_date, delivered_date, cost, status, carrier_status, first_value(cost, true) over (partition by status order by delivered_date, id rows between unbounded preceding and current row) as first_known_cost, rank() over (partition by status order by cost nulls last) as cost_rank from valid), ranked as (select * from enriched qualify row_number() over (partition by order_id, carrier order by shipped_date, id) = 1), enriched_shipments as (select *, lead(first_known_cost, 2) over (partition by carrier order by cost_rank, id) as next_first_known_cost, round(cost_rank / sum(cost_rank) over (partition by status, order_id), 4) as cost_rank_share, percent_rank() over (partition by carrier order by cost desc) as cost_percent_rank from ranked), joined as (select a.*, d.shipping_fee, d.amount from enriched_shipments a join orders d on a.order_id = d.id), matched_keys as (select id, carrier from joined intersect all select id, carrier from shipments where cost between 45 and 71), verified as (select s.* from joined s join matched_keys k on s.id = k.id and s.carrier = k.carrier), scored as (select id, order_id, carrier, shipped_date, delivered_date, cost, status, carrier_status, first_known_cost, cost_rank, next_first_known_cost, cost_rank_share, cost_percent_rank, shipping_fee, amount, stddev_samp(shipping_fee) over (partition by status) as status_stddev_samp_shipping_fee, stddev_samp(first_known_cost) over (partition by carrier, status) as carrier_stddev_samp_first_known_cost from verified) select shipped_date, delivered_date, cost, status, carrier_status, first_known_cost, cost_rank_share, cost_percent_rank, amount from scored;
